script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var requestObj = {
        "sysparm_email_verification_mode": api.data.email_verification_controller.initialData.mode,
        "sysparm_answer_email_code": api.data.email_verification_controller.emailCode
    };
    return {
        requestDetail: requestObj,
        errorMessagePrefix: "Incorrect verification code entered."
    };
}
